// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"proof-of-stake":{"slug":"proof-of-stake","cat":"basics","en":"Proof of stake (PoS)","contentLocale":"ja","term":"プルーフ・オブ・ステーク（PoS）","aka":["PoS","Proof of Stake"],"short":"プルーフ・オブ・ステーク（PoS）とは、暗号資産を担保として預け入れ（ステーク）したバリデーターが、ブロックの提案と検証を担うコンセンサスの仕組みです。","body":[["PoWが計算力で競うのに対し、PoSでは資産を差し出すことがネットワークに参加する条件になります。",["バリデーター","validator"],"は正しく働けば報酬を受け取り、二重署名などの不正をすると",["ステーク","staking"],"の一部を没収される「スラッシング」というペナルティを受けます。"],[["イーサリアム","ethereum"],"は2022年9月のThe MergeでPoSに移行し、自分でバリデーターを1つ動かすには32 ETHが必要です。ソラナやカルダノなど多くのチェーンもPoS系の仕組みを採用しています。大量の計算をしないため、電力消費はPoWより大幅に少なくなります。"],["一般の保有者は、自分でバリデーターを運用しなくても、取引所の",["ステーキングサービス","crypto-earn"],"、",["リキッドステーキング","liquid-staking"],"、委任（デリゲート）を通じて報酬を得られます。ただし、ロック期間、手数料、スラッシング時の負担の仕方はサービスごとに異なります。"]],"example":"例えば、年3%の報酬が見込めるステーキングに10 ETHを預けると、1年後の報酬は約0.3 ETHです。ただし、ETHの価格が1 ETH = 50万円から40万円に下がれば、元の10 ETHの評価額は500万円から400万円に減ります。報酬の0.3 ETH（約12万円）では、100万円の値下がりを埋められません。","mistakes":["ステーキング報酬があれば価格下落のリスクも相殺できると考えること。","アンステーク（引き出し）に待ち時間がある場合があることを知らずに預けること。","PoSのチェーンなら誰でも同じ利率の報酬がもらえると思い込むこと。"],"faq":[{"q":"PoSは安全ですか？","a":"不正をするとステークを失うため、攻撃には巨額の資産が必要になる仕組みです。ただし、ステークが一部の事業者に集中しすぎると、中央集権化の懸念が生じます。"},{"q":"32 ETHがないとイーサリアムのステーキングはできませんか？","a":"自分でバリデーターを動かすには32 ETHが必要ですが、取引所のサービスやリキッドステーキングを使えば少額から参加できます。"}],"title":"プルーフ・オブ・ステーク（PoS）とは？PoWとの違い","description":"プルーフ・オブ・ステーク（PoS）の仕組み、バリデーターとスラッシング、PoWとの違いを初心者向けに解説します。","related":[["staking","ステーキング","ステーキングとは、プルーフ・オブ・ステーク型のブロックチェーンで暗号資産を預け入れてネットワークの運営に参加し、その対価として報酬を受け取る仕組みです。"],["liquid-staking","リキッドステーキング","リキッドステーキングとは、暗号資産をステーキングすると同時に、その預け入れを表すトークンを受け取り、ロックされた資産を他の用途にも使えるようにする仕組みです。"],["proof-of-work","プルーフ・オブ・ワーク（PoW）","プルーフ・オブ・ワーク（PoW）とは、マイナーが大量の計算で競争し、最初に条件を満たす答えを見つけた者が新しいブロックを追加できるコンセンサスの仕組みです。"],["validator","バリデーター（検証者）","バリデーターとは、プルーフ・オブ・ステークのブロックチェーンで暗号資産をステークし、ブロックの提案や取引の検証を行うネットワーク参加者のことです。"],["ethereum","イーサリアム（ETH）","イーサリアム（ETH）とは、スマートコントラクトを実行できるブロックチェーンと、その手数料の支払いやステーキングに使われるネイティブ暗号資産ETHのことです。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"volatility":{"slug":"volatility","cat":"basics","en":"Volatility","contentLocale":"ja","term":"ボラティリティ（価格変動率）","aka":["ボラ","Volatility"],"short":"ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。","body":["ボラティリティが高いとは、短時間で価格が上にも下にも大きく動くことを意味します。統計的には価格変化率の標準偏差で測られ、年率に換算して示されることが多いです。日常的には「ボラが大きい」「ボラが落ち着いた」などと言います。",[["暗号資産","cryptocurrency"],"は24時間365日取引され、市場規模が株式より小さく、",["レバレッジ取引","margin-trading"],"も活発なため、ボラティリティが高くなりやすいです。一般に、",["ビットコイン","bitcoin"],"より",["アルトコイン","altcoin"],"、大型銘柄より小型銘柄のほうが変動は大きくなります。",["ステーブルコイン","stablecoin"],"は逆に、価格を一定に保つよう設計されています。"],["ボラティリティはチャンスであると同時にリスクでもあります。",["レバレッジ","leverage"],"をかけるほど、同じ値動きでも損益は大きくなり、強制ロスカットの可能性が高まります。値動きの大きい銘柄では、ポジションを小さくし、損切りの幅を値動きに合わせて設定することが大切です。"]],"example":"例えば、1日の値動きが平均3%の銘柄Aと、平均12%の銘柄Bがあるとします。どちらも1回の損失を1万円に抑えたいとき、損切り幅を1日の平均的な値動き程度に置くなら、ポジションの目安はAが約33万円、Bが約8万3,000円です。値動きが大きい銘柄ほど、持てる量は小さくなります。","mistakes":["値動きの大きさを考えずに、すべての銘柄で同じ金額のポジションを持つこと。","ボラティリティの高い銘柄に高いレバレッジをかけること。","値動きが落ち着いている期間がこの先も続くと思い込むこと。"],"faq":[{"q":"ボラティリティが高いのは悪いことですか？","a":"良し悪しではなく、利益と損失の両方の振れ幅が大きいということです。自分が許容できる変動の大きさに合わせて、銘柄や取引量を選ぶことが大切です。"},{"q":"暗号資産のボラティリティはなぜ高いのですか？","a":"市場規模が比較的小さいこと、24時間取引されること、レバレッジ取引が多いこと、ニュースへの反応が大きいことなどが理由に挙げられます。"}],"title":"ボラティリティとは？意味と暗号資産の値動きの特徴","description":"ボラティリティ（価格変動率）の意味と測り方、暗号資産の値動きが大きい理由、リスク管理への活かし方を解説します。","related":[["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"],["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"],["position-sizing","ポジションサイジング（建玉管理）","ポジションサイジングとは、1回の取引でどれだけの数量を建てるかを、許容できる損失額と損切りまでの距離から逆算して決める資金管理の方法です。"],["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"stop-limit-order":{"slug":"stop-limit-order","cat":"trading","en":"Stop-limit order","contentLocale":"ja","term":"ストップリミット注文","aka":["ストップリミット","ストップ指値","Stop-limit"],"short":"ストップリミット注文とは、価格がトリガー価格（ストップ価格）に達したときに、あらかじめ指定した価格で指値注文を自動発注する注文方法です。","body":[["設定する価格は2つあります。注文を発動させる「ストップ価格」と、実際に出す指値の「リミット価格」です。",["損切り","stop-loss"],"で使う場合は、ストップ価格を95、リミット価格を94.5のように、少し不利な側に余裕を持たせて設定するのが一般的です。"],["ストップ",["成行注文","market-order"],"（ストップマーケット）との違いは約定価格の扱いです。ストップ成行はトリガー後に成行で発注されるため約定はほぼ確実ですが、価格がずれることがあります。ストップリミットは指定価格より不利には約定しない代わりに、価格が一気にリミット価格を飛び越えると約定しないことがあります。"],["そのため損切りで使う場合は、約定しないリスクの方が大きな問題になり得ます。値動きの激しい銘柄や",["レバレッジ取引","margin-trading"],"では、ストップ価格とリミット価格の間を十分に空けるか、ストップ成行を使うかを検討しましょう。高値を上抜けたら買うといったエントリーにも使えます。"]],"example":"例えば、ETHを3,000ドルで1 ETH保有し、ストップ価格2,850ドル、リミット価格2,840ドルの売り注文を設定したとします。価格がゆっくり下がれば2,840〜2,850ドル付近で売れ、損失は約150〜160ドルです。しかし悪材料で2,850ドルから一気に2,780ドルまで下落すると、2,840ドルの売り指値は約定せず、損失は220ドル以上に広がり、さらに下がり続ける可能性もあります。","mistakes":["ストップ価格とリミット価格を同じ値にして、急落時に約定しにくい状態を作ること。","売りのストップリミットで、リミット価格をストップ価格より上に設定してしまうこと。","発動したのに約定していない指値注文が板に残っていることに気づかないこと。"],"faq":[{"q":"ストップリミットとストップ成行はどちらを使うべきですか？","a":"確実に決済したい損切りではストップ成行、約定価格を優先したい場合はストップリミットが向いています。値動きや流動性に応じて選びます。"},{"q":"逆指値とストップリミットは同じですか？","a":"逆指値は、価格が条件に達したら注文を出す仕組みの総称です。ストップリミットは、その発注を指値で行う形式です。呼び方は取引所ごとに異なります。"}],"title":"ストップリミット注文とは？逆指値との違いと注意点","description":"ストップリミット注文の仕組み、ストップ価格とリミット価格の設定方法、ストップ成行との違いと約定しないリスクを解説します。","related":[["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"],["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。"],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。"],["trailing-stop","トレーリングストップ","トレーリングストップとは、価格が有利な方向に動くと損切り価格も自動で追いかけて移動し、反転して一定幅戻ったときに決済する注文です。"]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"利確と損切りは計画であって、保険ではない"},"coin":null,"tool":null,"cta":false},"time-in-force":{"slug":"time-in-force","cat":"trading","en":"Time in force (GTC, IOC, FOK)","contentLocale":"ja","term":"執行条件（GTC・IOC・FOK）","aka":["GTC","IOC","FOK","Time in force"],"short":"執行条件（タイムインフォース）とは、注文をいつまで有効にし、約定しなかった分をどう扱うかを決める設定で、代表的なものにGTC・IOC・FOKがあります。","body":[["GTC（Good Till Cancelled）は、約定するか自分で取り消すまで有効な注文です。多くの取引所で",["指値注文","limit-order"],"の初期設定になっています。ただし取引所によっては、長期間残った注文を自動で取り消す場合もあります。"],"IOC（Immediate Or Cancel）は、すぐに約定できる分だけを約定させ、残りは即座に取り消します。FOK（Fill Or Kill）は、注文の全量がすぐに約定できる場合のみ約定させ、一部しか約定できないなら全量を取り消します。どちらも板に注文が残らない点が共通です。","使い分けの例として、GTCは指定価格で気長に待つとき、IOCは今ある板の範囲でできるだけ約定させたいとき、FOKは全部約定しないなら不要というときに向いています。日本の取引所では「有効期限」として当日限りや期間指定を選べる場合もあり、名称や選択肢は取引所ごとに異なります。"],"example":"例えば、60,000ドルの指値で2 BTCを買う注文を出し、その価格以下の売り注文が板に1.2 BTCしかないとします。GTCなら1.2 BTCが約定し、残りの0.8 BTCは板に残って待ちます。IOCなら1.2 BTCが約定して0.8 BTCは取り消されます。FOKなら全量の2 BTCが揃わないため、注文全体が取り消されて何も約定しません。","mistakes":["GTCの古い指値注文を残したまま忘れ、相場が急変したときに思わぬ約定をすること。","IOCで全量が買えたと思い込み、一部しか約定していないことに気づかないこと。","流動性の低い銘柄でFOKを使い、何度出しても約定しない理由が分からないこと。"],"faq":[{"q":"GTCとIOCの違いは何ですか？","a":"GTCは約定しなかった分も板に残して待ち、IOCはすぐに約定しなかった分を即座に取り消します。"},{"q":"執行条件を指定しないとどうなりますか？","a":"多くの取引所では、指値注文はGTCとして扱われます。初期設定は取引所によって異なるため、注文画面で確認しましょう。"}],"title":"GTC・IOC・FOKとは？注文の執行条件をわかりやすく解説","description":"注文の執行条件GTC・IOC・FOKの意味と違い、部分約定の扱い、使い分けの例を具体的な数字で解説します。","related":[["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。"],["post-only-order","ポストオンリー注文","ポストオンリー注文とは、板に並ぶメイカー注文としてのみ受け付けられ、すぐに約定してテイカーになる場合は自動で取り消される指値注文の設定です。"],["market-order","成行注文","成行注文とは、価格を指定せずに、その時点で板にある最も有利な価格から順に、すぐに売買を成立させる注文方法です。"],["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"成行、指値、キャンセル：それぞれ何を解決するのか？"},"coin":null,"tool":null,"cta":false},"private-key":{"slug":"private-key","cat":"wallets-security","en":"Private key","contentLocale":"ja","term":"秘密鍵（プライベートキー）","aka":["プライベートキー","private key","秘密キー"],"short":"秘密鍵とは、暗号資産のアドレスから送金するための電子署名を作る秘密の数値で、これを持つ人がそのアドレスの資産を自由に動かせます。","body":[[["ビットコイン","bitcoin"],"や",["イーサリアム","ethereum"],"の秘密鍵は、256ビットの巨大な乱数です。ここから",["公開鍵","public-key"],"が計算され、さらに",["ウォレットアドレス","wallet-address"],"が作られます。逆方向の計算、つまりアドレスから秘密鍵を求めることは現実的にできません。"],["送金するとき、",["ウォレット","crypto-wallet"],"は秘密鍵で取引に署名し、ネットワークはその署名が正しいかを公開鍵で検証します。秘密鍵そのものはネットワークに送られません。"],[["暗号資産","cryptocurrency"],"の世界では「鍵を持つ人が持ち主」です。取引所に預けた資産の秘密鍵は取引所が管理し、自分のウォレットなら自分が管理します。秘密鍵が漏れれば、取り消しや差し戻しはできません。"]],"example":"256ビットの秘密鍵は、2の256乗、およそ1.16かける10の77乗通りの候補から選ばれます。仮に毎秒1兆個の鍵を試せるコンピューターがあっても、全体のごく一部すら調べ終わりません。ところが、あなたが64桁の16進数で表示された秘密鍵を偽サイトに1回貼り付けるだけで、相手はそのアドレスにある0.8 ETHでも8 ETHでも、すぐに引き出せます。","mistakes":["秘密鍵をエクスポートして、チャットやメールで送ってしまうこと。","秘密鍵を公開鍵やウォレットアドレスと混同して、他人に見せてしまうこと。","復元手段がシードフレーズなのか秘密鍵なのかを確認せずにウォレットを削除すること。"],"faq":[{"q":"秘密鍵は変更できますか？","a":"同じアドレスの秘密鍵を変更することはできません。漏洩が疑われるときは、新しいウォレットを作って資産を移すしかありません。"},{"q":"秘密鍵とパスワードは同じものですか？","a":"違います。ウォレットアプリのパスワードは端末上のロックにすぎず、秘密鍵やシードフレーズがあれば別の端末からでも資産を動かせます。"}],"title":"秘密鍵とは？意味と公開鍵・アドレスとの関係","description":"暗号資産の秘密鍵（プライベートキー）とは何か、公開鍵やアドレスとの関係、漏洩したときに起こることを具体例で解説します。","related":[["seed-phrase","シードフレーズ（リカバリーフレーズ）","シードフレーズとは、ウォレットの秘密鍵をすべて復元できる12語または24語の英単語の並びで、ウォレットのマスターキーにあたるものです。"],["public-key","公開鍵（パブリックキー）","公開鍵とは、秘密鍵から計算される暗号の鍵で、取引の署名が正しい秘密鍵で作られたかを誰でも検証できるようにするものです。"],["wallet-address","ウォレットアドレス","ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。"],["multisig-wallet","マルチシグウォレット","マルチシグウォレットとは、送金に複数の秘密鍵の署名を必要とするウォレットで、たとえば3つの鍵のうち2つの署名がそろわないと資産を動かせない仕組みです。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"私のコインはどこ？取引所とウォレットの違い"},"coin":null,"tool":null,"cta":false},"amm":{"slug":"amm","cat":"defi","en":"Automated market maker (AMM)","contentLocale":"ja","term":"AMM（自動マーケットメーカー）","aka":["自動マーケットメーカー","AMM","オートメイテッド・マーケットメーカー"],"short":"AMM（自動マーケットメーカー）とは、板で売り手と買い手を突き合わせる代わりに、流動性プールと数式で自動的に価格を決めて取引を成立させる仕組みです。","body":[["通常の取引所は、買い注文と売り注文を",["板（オーダーブック）","order-book"],"でマッチングします。AMMでは、利用者が2種類のトークンを預けた",["流動性プール","liquidity-pool"],"が取引相手になり、プール内の数量の比率から価格が決まります。"],"Uniswapなどで広く使われる定数積方式では、2つのトークンの数量の積が一定（x かける y イコール k）になるように取引されます。あるトークンを買うとプール内の量が減り、その分だけ価格が上がる仕組みです。",["AMMのおかげで、",["マーケットメーカー","market-maker"],"がいない新しいトークンでも24時間取引できます。ただし、プールが小さいほど1回の取引で価格が大きく動き、",["スリッページ","slippage"],"が大きくなります。",["流動性","liquidity"],"提供者は",["インパーマネントロス","impermanent-loss"],"のリスクも負います。"]],"example":"プールに100 ETHと300,000 USDCがあるとします。積kは3,000万、表示価格は1 ETHあたり3,000 USDCです。ここで30,000 USDCを入れてETHを買うと、USDCは330,000になり、ETHは3,000万を330,000で割った約90.91になります。受け取れるのは約9.09 ETHで、平均価格は約3,300 USDCです。手数料を除いても、プールに対して大きな注文ほど不利な価格になることが分かります。","mistakes":["表示価格のまま約定すると思い込み、プールの規模と注文サイズの関係を考えないこと。","スリッページ許容値を大きくしすぎて、サンドイッチ攻撃の標的になること。","流動性を提供すれば手数料収入だけが得られると思い、価格変動の影響を考えないこと。"],"faq":[{"q":"AMMの価格はどうやって市場価格と一致するのですか？","a":"プールの価格が他の取引所とずれると、アービトラージャーが安い方で買って高い方で売ります。この取引によってプールの比率が調整され、市場価格に近づきます。"},{"q":"AMMと板取引はどちらが有利ですか？","a":"流動性が厚い主要銘柄では板取引の方がコストが低いことが多いです。AMMは、板がない新しいトークンを取引できる点や、誰でも流動性を提供できる点が強みです。"}],"title":"AMM（自動マーケットメーカー）とは？仕組みと計算例","description":"AMM（自動マーケットメーカー）の意味、定数積方式による価格の決まり方、大きな注文でスリッページが生じる理由を計算例で解説します。","related":[["liquidity-pool","流動性プール（リクイディティプール）","流動性プールとは、DEXで取引相手として機能するように、利用者が2種類以上のトークンを預け入れてつくる資金の集まりで、預けた人は取引手数料の一部を受け取ります。"],["impermanent-loss","インパーマネントロス（変動損失）","インパーマネントロスとは、AMMの流動性プールに資産を預けている間にトークンの価格比が変わることで、単に保有していた場合より資産価値が少なくなる損失のことです。"],["dex","DEX（分散型取引所）","DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。"],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"staking":{"slug":"staking","cat":"defi","en":"Staking","contentLocale":"ja","term":"ステーキング","aka":["staking","ステーク","ステーキング報酬"],"short":"ステーキングとは、プルーフ・オブ・ステーク型のブロックチェーンで暗号資産を預け入れてネットワークの運営に参加し、その対価として報酬を受け取る仕組みです。","body":[[["イーサリアム","ethereum"],"、ソラナ、カルダノなどの",["プルーフ・オブ・ステーク","proof-of-stake"],"型チェーンでは、資産をステークした",["バリデーター","validator"],"が取引を検証し、ブロックを作ります。正しく役割を果たすと報酬が支払われ、不正や重大なミスがあるとステークの一部を没収（スラッシング）されることがあります。"],["参加方法は主に3つです。自分でバリデーターを運用する方法、他のバリデーターに委任する方法、取引所の",["ステーキングサービス","crypto-earn"],"を使う方法です。取引所を使えば手軽ですが、資産を取引所に預けることになり、手数料が差し引かれます。"],["注意点は、ロック期間や引き出しまでの待機期間があることと、報酬が",["暗号資産","cryptocurrency"],"で支払われるため円建ての価値は価格次第であることです。ステーキングの条件は銘柄や取引所ごとに異なるため、事前に確認しましょう。"]],"example":"あなたが100 SOLをステーキングし、年率6%で報酬が付くと仮定します。1年後の報酬は6 SOLで、合計106 SOLになります。ステーク開始時にSOLが2万円なら元本は200万円ですが、1年後にSOLが1万5,000円に下がっていれば、106 SOLの価値は159万円です。数量は増えても、円建てでは41万円のマイナスになります。報酬率と価格変動は別物として考える必要があります。","mistakes":["ロック期間や解除の待機期間を確認せず、すぐに売れると思ってステークすること。","報酬率だけを見て、価格下落で円建ての価値が減る可能性を考えないこと。","異常に高い報酬率をうたう、聞いたことのないステーキングサイトに資産を送ること。"],"faq":[{"q":"ステーキングで元本が減ることはありますか？","a":"数量は通常減りませんが、価格が下がれば円建ての価値は減ります。バリデーターがスラッシングを受けた場合や、預け先が破綻した場合は数量自体が減る可能性もあります。"},{"q":"ステーキング報酬に税金はかかりますか？","a":"多くの国で報酬は課税対象とされていますが、扱いは国や制度によって異なります。日本では一般的に雑所得として扱われることが多いため、最新の税務情報を確認しましょう。"}],"title":"ステーキングとは？仕組みと報酬・リスクの基本","description":"暗号資産のステーキングの意味、プルーフ・オブ・ステークとの関係、取引所と自分で行う方法の違い、ロック期間や価格変動のリスクを解説します。","related":[["proof-of-stake","プルーフ・オブ・ステーク（PoS）","プルーフ・オブ・ステーク（PoS）とは、暗号資産を担保として預け入れ（ステーク）したバリデーターが、ブロックの提案と検証を担うコンセンサスの仕組みです。"],["liquid-staking","リキッドステーキング","リキッドステーキングとは、暗号資産をステーキングすると同時に、その預け入れを表すトークンを受け取り、ロックされた資産を他の用途にも使えるようにする仕組みです。"],["validator","バリデーター（検証者）","バリデーターとは、プルーフ・オブ・ステークのブロックチェーンで暗号資産をステークし、ブロックの提案や取引の検証を行うネットワーク参加者のことです。"],["crypto-earn","暗号資産の運用サービス（Earn）","暗号資産の運用サービス（Earn）とは、取引所に預けた暗号資産を貸し出しやステーキングなどに回し、利息や報酬を受け取れる取引所の商品群のことです。"],["apr-vs-apy","APRとAPYの違い（年利・年間利回り）","APRは複利を含まない単純な年利、APYは得た利息を再投資する複利効果を含めた年間利回りで、同じ金利でもAPYの方が高い数字になります。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"total-value-locked":{"slug":"total-value-locked","cat":"defi","en":"Total value locked (TVL)","contentLocale":"ja","term":"TVL（預かり資産総額）","aka":["TVL","Total Value Locked","ロックされた総価値","預かり資産"],"short":"TVLとは、DeFiのプロトコルやブロックチェーンに預けられている暗号資産の総額をドルなどで表した指標で、利用規模の目安として使われます。","body":[["レンディングに預けられた資産、DEXの",["流動性プール","liquidity-pool"],"、",["ステーキング","staking"],"された資産などを合計して計算されます。DefiLlamaなどの集計サイトで、プロトコルごと、チェーンごとのTVLを比較できます。"],"TVLが大きいほど多くの資金が集まっていることを示しますが、安全性を保証するものではありません。大きなTVLはハッカーにとって魅力的な標的にもなります。","TVLは預けられた資産の価格に強く左右されます。資金が流出していなくても、ETHなどの価格が下がればTVLは減ります。また、同じ資産が複数のプロトコルで重複して数えられることもあるため、数字だけで判断せず、資金の流入出や手数料収入などもあわせて見ましょう。"],"example":["ある",["レンディングプロトコル","defi-lending"],"に100,000 ETHが預けられていて、ETHが2,000ドルならTVLは2億ドルです。翌月、預け入れ量はまったく変わらないままETHが1,500ドルに下がると、TVLは1億5,000万ドルになり、25%減ったように見えます。逆に、同じ期間に10,000 ETHが引き出されていても、ETHが2,400ドルに上がればTVLは2億1,600万ドルとなり、増えたように見えます。"],"mistakes":["TVLが大きいプロトコルは安全だと考え、監査やリスクを確認しないこと。","TVLの増減を、価格変動によるものか資金の流入出によるものか区別しないこと。","TVLと時価総額を同じ指標だと混同すること。"],"faq":[{"q":"TVLと時価総額の違いは何ですか？","a":"TVLはプロトコルに預けられた資産の総額で、時価総額はそのプロジェクトのトークンの発行済み数量に価格をかけた値です。両方を比べることで、評価の割高・割安を見る参考にする人もいます。"},{"q":"TVLが急に増えるのは良いことですか？","a":"利用が増えている可能性がありますが、一時的な報酬キャンペーンで資金が集まっているだけのこともあります。報酬が終わると急減する例も多いため、増加の理由を確認しましょう。"}],"title":"TVLとは？DeFiの預かり資産総額の意味と見方","description":"DeFiのTVL（Total Value Locked）の意味、計算方法、価格変動による増減や重複計上など、数字を見るときの注意点を解説します。","related":[["defi","DeFi（分散型金融）","DeFi（分散型金融）とは、銀行や取引所などの仲介者を通さず、ブロックチェーン上のスマートコントラクトで交換、貸し借り、利回り運用などを行う金融サービスの総称です。"],["liquidity-pool","流動性プール（リクイディティプール）","流動性プールとは、DEXで取引相手として機能するように、利用者が2種類以上のトークンを預け入れてつくる資金の集まりで、預けた人は取引手数料の一部を受け取ります。"],["defi-lending","DeFiレンディング","DeFiレンディングとは、スマートコントラクト上で暗号資産を貸し出して利息を得たり、担保を預けて別の暗号資産を借りたりできる仕組みです。"],["market-capitalization","時価総額（マーケットキャップ）","時価総額（マーケットキャップ）とは、暗号資産の現在価格に流通供給量を掛けた値で、その銘柄の市場規模を比べるための基本的な指標です。"]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"depeg":{"slug":"depeg","cat":"stablecoins","en":"Depeg","contentLocale":"ja","term":"デペッグ（Depeg）","aka":["ペッグ外れ","depeg"],"short":"デペッグとは、1ドルなど特定の価値に連動するよう設計されたステーブルコインやトークンの価格が、その目標値から大きく離れてしまう状態のことです。","body":[[["ステーブルコイン","stablecoin"],"は、裏付け資産や償還の仕組み、",["裁定取引","arbitrage"],"によって「1コイン＝1ドル」付近に価格を保っています。これを「ペッグ（固定）」と呼びます。裏付け資産への不安、償還の停止、",["流動性","liquidity"],"の急減などが起きると、市場価格が0.99ドル、0.95ドルと目標から外れていきます。これがデペッグです。"],["数ミリ単位の小さなズレは日常的に起こり、裁定取引によってすぐ戻ることが多いです。問題になるのは、発行体の信用不安や担保の毀損など、仕組みそのものが揺らいだときです。",["ステーキング報酬","staking"],"付きの",["リキッドステーキングトークン","liquid-staking"],"でも、元の資産との価格差が広がることをデペッグと呼ぶことがあります。"],["取引所ごとに板の厚さが違うため、同じコインでも表示価格がわずかに異なります。デペッグ時は一部の取引所や",["分散型取引所","dex"],"（DEX）だけ大きく値崩れすることもあるので、複数の市場の価格を確認することが大切です。"]],"example":"あなたが10,000 USDCを保有していて、ある日、市場価格が0.97ドルまで下がったとします。このタイミングで慌てて売ると、受け取れるのは約9,700ドル相当で、300ドルの損失が確定します。一方で、発行体が1ドルでの償還を継続し、価格が数日で1.00ドルに戻れば、売らなかった人の評価額は10,000ドルに戻ります。逆に償還が止まれば戻らない可能性もあるため、価格だけでなく発行体の公式発表と償還状況を確認することが判断の材料になります。","mistakes":["ステーブルコインは絶対に1ドルから動かないと思い込み、資産のすべてを1種類のステーブルコインに置いてしまう。","0.999ドル程度の通常の小さな値動きをデペッグと勘違いし、手数料を払って何度も乗り換えてしまう。","1つの取引所の価格だけを見て判断し、他の市場では価格が正常に戻っていることに気づかない。"],"faq":[{"q":"デペッグしたステーブルコインは元に戻りますか？","a":"裏付け資産が十分で償還が機能していれば、裁定取引によって戻ることが多いです。ただし担保が毀損していたり、仕組みが崩れていたりする場合は戻らないこともあります。"},{"q":"デペッグはなぜ起きるのですか？","a":"主な原因は、裏付け資産への不安、償還の停止、大量の売り注文による流動性不足です。アルゴリズム型のステーブルコインは、需要が急減したときに特にデペッグしやすい構造です。"}],"title":"デペッグとは？ステーブルコインの価格が外れる意味","description":"デペッグの意味、ステーブルコインが1ドルから外れる原因、価格が戻るケースと戻らないケース、保有者が確認すべき点をわかりやすく解説します。","related":[["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"],["algorithmic-stablecoin","アルゴリズム型ステーブルコイン","アルゴリズム型ステーブルコインとは、十分な担保ではなく、供給量を自動調整するプログラムや別トークンとの交換の仕組みによって価格を1ドルに保とうとするステーブルコインです。"],["usdc","USDC（USDコイン）","USDCとは、米国のCircle社が発行する米ドル連動型のステーブルコインで、現金と米国短期国債などを裏付けに1 USDCが約1ドルになるよう設計されています。"],["liquid-staking","リキッドステーキング","リキッドステーキングとは、暗号資産をステーキングすると同時に、その預け入れを表すトークンを受け取り、ロックされた資産を他の用途にも使えるようにする仕組みです。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDTは米ドルですか？なぜ暗号資産を買う時によく見かけるの？"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false},"real-world-assets":{"slug":"real-world-assets","cat":"tokenized-assets","en":"Real-world assets (RWA)","contentLocale":"ja","term":"RWA（現実資産のトークン化）","aka":["RWA","現実資産","リアルワールドアセット","Real World Assets"],"short":"RWAとは、国債、株式、不動産、金、貸付債権など、ブロックチェーンの外にある現実の資産を、トークンとしてブロックチェーン上で表現したもの、またはその分野のことです。","body":["RWAは「Real World Assets」の略です。現実の資産を、信託や特別目的会社などの仕組みで保有し、その権利をトークンとして発行します。トークン化された米国債、金、株式、不動産の持分、民間の貸付などがあり、Ondo Financeのように国債のトークン化で知られるプロジェクトもあります。",["RWAの利点は、24時間の送金、小口での保有、DeFiでの担保利用などがしやすくなることです。たとえば、国債の利回りを",["ブロックチェーン","blockchain"],"上で受け取れるトークンは、",["ステーブルコイン","stablecoin"],"を保有している人の運用先として注目されています。"],["一方で、RWAの価値はブロックチェーンの外にある資産と、それを保管・管理する発行体に依存します。発行体の信用、裏付け資産の監査、償還の条件、購入に必要なKYCや居住国の制限などを確認することが、",["暗号資産","cryptocurrency"],"だけの商品よりも重要になります。"]],"example":"ある不動産の持分を1,000,000ドル分トークン化し、1トークン＝100ドルで10,000枚発行したとします。あなたは500ドルで5枚を購入しました。この不動産の年間の賃料収入から経費を引いた分配金が50,000ドルなら、利回りは5%で、あなたの取り分は年25ドルです。ただし、トークンを売りたいときに買い手が少なければ、希望する価格で売れないこともあります。また、管理会社が経営難になった場合、トークンの権利がどう扱われるかは発行の仕組みと契約次第です。","mistakes":["ブロックチェーン上のトークンだから、裏付け資産の管理者を信用する必要がないと考える。","表示される利回りだけを見て、売りたいときの流動性の低さを考慮しない。","購入に必要なKYCや居住国の制限を確認せず、償還や受け取りができなくなる。"],"faq":[{"q":"RWAとステーブルコインは関係がありますか？","a":"法定通貨担保型のステーブルコインは、現金や短期国債を裏付けにしているため、広い意味でRWAの一種と見なされることがあります。"},{"q":"RWAトークンは誰でも買えますか？","a":"商品によって異なります。多くは本人確認が必要で、国によっては購入できない場合もあります。"}],"title":"RWAとは？現実資産のトークン化の意味と仕組み","description":"RWA（現実資産のトークン化）の意味と仕組み、国債・不動産・金などの例、発行体の信用や流動性など確認すべきリスクを解説します。","related":[["tokenized-treasuries","トークン化国債","トークン化国債とは、米国債などの国債や、国債で運用するファンドの持分をブロックチェーン上のトークンとして発行し、その利回りをオンチェーンで受け取れるようにしたものです。"],["tokenized-stocks","トークン化株式","トークン化株式とは、実際の株式や株式に連動する権利をブロックチェーン上のトークンとして発行し、暗号資産と同じように保有や送金ができるようにしたものです。"],["tokenized-gold","トークン化ゴールド（金トークン）","トークン化ゴールドとは、発行体が保管する現物の金に裏付けられ、その金の一定量を表すトークンとしてブロックチェーン上で取引できる暗号資産のことです。"],["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-assets","cta":false}});
